WITH base AS (SELECT * FROM departments WHERE location IN ('Bangkok', 'Chiang Mai') AND budget BETWEEN 3032000 AND 3706000), departments_stats AS (SELECT location, dept_name, SUM(CASE WHEN location = 'Chiang Mai' THEN budget ELSE 0 END) AS chiang_mai_budget, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM base GROUP BY location, dept_name) SELECT location, dept_name, chiang_mai_budget, dept_name_list FROM departments_stats ORDER BY chiang_mai_budget DESC, location, dept_name LIMIT 50
